#nullable enable // autogenerated

using System.Collections.Generic;
using System.Linq;
using MVZ2.Audios;
using MVZ2.Metas;
using PVZEngine;
using UnityEngine;

namespace MVZ2.Resources
{
    public class SoundMetaResolver : ResourceResolver<NamespaceID, ISoundMeta> 
    {
        protected override List<NamespaceID> BuildCandidateKeys(NamespaceID key, ResourceContext context)
        {
            var list = new List<NamespaceID>();
            list.Add(key);
            return list;
        }
    }
}
